远程调用在订单提交返回之后。超时写在客户端：

```java
@FeignClient("resource-lock")
public interface LockClient {
  @PostMapping("/reservations")
  LockResult reserve(@RequestHeader("Idempotency-Key") String idemKey,
      @RequestBody ReserveRequest body);
}

@Service
public class OrderTx {
  @Transactional
  public void insertPending(String orderId, String skuId, int qty) {
    orders.insert(orderId, skuId, qty, "PENDING");
  }

  @Transactional
  public void markFailed(String orderId) {
    orders.updateStatus(orderId, "PENDING", "FAILED");
  }
}

@Service
public class PlaceOrder {
  public String place(String orderId, String skuId, int qty, String idemKey) {
    orderTx.insertPending(orderId, skuId, qty);
    try {
      LockResult locked = locks.reserve(idemKey, new ReserveRequest(orderId, skuId, qty));
      if (locked == LockResult.REJECTED) orderTx.markFailed(orderId);
    } catch (feign.FeignException ex) {
      LockResult again = locks.reserve(idemKey, new ReserveRequest(orderId, skuId, qty));
      if (again != LockResult.RESERVED) orderTx.markFailed(orderId);
    }
    return orderId;
  }
}
```

